{
  "text": "Hi, this is an agent reply sent from Postman"
}

{
  "name": "Postman test welcome flow",
  "definition": {
    "entryNodeId": "n1",
    "nodes": [
      {
        "id": "n1",
        "type": "message",
        "text": "Hi! Welcome.",
        "next": "n2"
      },
      {
        "id": "n2",
        "type": "input",
        "prompt": "What is your name?",
        "saveAs": "name",
        "next": "n3"
      },
      {
        "id": "n3",
        "type": "message",
        "text": "Nice to meet you!",
        "next": "n4"
      },
      {
        "id": "n4",
        "type": "end"
      }
    ]
  }
}

{
  "channelId": "{{whatsappChannelId}}",
  "name": "Postman test broadcast",
  "type": "broadcast",
  "contactIds": [
    "{{contactId}}"
  ],
  "definition": {
    "text": "Hi {{name}}, this is a test broadcast from Postman!"
  }
}
